function save(){const temp=DATA+"."+process.pid+"."+crypto.randomBytes(6).toString("hex")+".tmp";try{fs.mkdirSync(DATA_DIR,{recursive:true});const payload=JSON.stringify(store,null,2);fs.writeFileSync(temp,payload,{encoding:"utf8",flag:"wx",mode:0o600});fs.renameSync(temp,DATA)}catch(error){try{if(fs.existsSync(temp))fs.unlinkSync(temp)}catch{}console.error("Could not save MLD data:",error.message);throw error}}
function id(){return crypto.randomUUID()}
function log(type,data){store.logs.unshift({id:id(),type,data,at:new Date().toISOString()});store.logs=store.logs.slice(0,3000);save()}
store.bots=Array.isArray(store.bots)?store.bots:[];store.games=Array.isArray(store.games)?store.games:[];store.settings=Object.assign({cinema:[],cinemaVoiceChannelId:""},store.settings||{});store.settings.cinema=Array.isArray(store.settings.cinema)?store.settings.cinema:[];
function cleanUser(u){if(!u)return null;return {id:u.id,username:u.username,displayName:u.displayName,avatar:u.avatar||"",bio:u.bio||"",role:u.role||"member",discordId:u.discordId||""}}
function jwtSecret(){return process.env.JWT_SECRET||process.env.DISCORD_BOT_TOKEN||process.env.DISCORD_TOKEN||process.env.OWNER_PASSWORD||""}
function createAccessToken(userId,expiresAt){if(!jwtSecret())return id();const head=Buffer.from(JSON.stringify({alg:"HS256",typ:"JWT"})).toString("base64url"),payload=Buffer.from(JSON.stringify({sub:userId,exp:Math.floor(expiresAt/1000),iat:Math.floor(Date.now()/1000)})).toString("base64url"),body=head+"."+payload,sig=crypto.createHmac("sha256",jwtSecret()).update(body).digest("base64url");return body+"."+sig}
function validJwt(token){try{const p=token.split(".");if(p.length!==3||!jwtSecret())return false;const expected=crypto.createHmac("sha256",jwtSecret()).update(p[0]+"."+p[1]).digest("base64url");const a=Buffer.from(p[2]),b=Buffer.from(expected);if(a.length!==b.length||!crypto.timingSafeEqual(a,b))return false;const payload=JSON.parse(Buffer.from(p[1],"base64url").toString("utf8"));return typeof payload.sub==="string"&&Number(payload.exp)*1000>Date.now()}catch{return false}}
function auth(req,res,next){const t=(req.headers.authorization||"").replace(/^Bearer\s+/,"");if(t.includes(".")&&!validJwt(t))return res.status(401).json({error:"جلسة الدخول غير صالحة أو منتهية"});const s=store.sessions.find(x=>x.token===t&&x.expires>Date.now());if(!s)return res.status(401).json({error:"تسجيل الدخول مطلوب"});req.user=store.users.find(x=>x.id===s.userId);if(!req.user)return res.status(401).json({error:"الحساب غير موجود"});next()}
function owner(req,res,next){if(req.user?.role!=="owner")return res.status(403).json({error:"هذه الصفحة للأونر فقط"});next()}
function admin(req,res,next){if(!["owner","admin"].includes(req.user?.role))return res.status(403).json({error:"صلاحية الإدارة مطلوبة"});next()}
