async function provisionGroup(g){if(!guild)return false;try{const role=await guild.roles.create({name:"MLD • "+g.name,reason:"MLD group"});const cat=await guild.channels.create({name:"◇ "+g.name,type:ChannelType.GuildCategory});const text=await guild.channels.create({name:"chat-"+g.name.toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g,"-").slice(0,70),type:ChannelType.GuildText,parent:cat.id,permissionOverwrites:[{id:guild.roles.everyone.id,deny:[PermissionFlagsBits.ViewChannel]},{id:role.id,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.SendMessages]}]});const voice=await guild.channels.create({name:"🔊 "+g.name,type:ChannelType.GuildVoice,parent:cat.id,permissionOverwrites:[{id:guild.roles.everyone.id,deny:[PermissionFlagsBits.ViewChannel]},{id:role.id,allow:[PermissionFlagsBits.ViewChannel,PermissionFlagsBits.Connect,PermissionFlagsBits.Speak]}]});g.discord={roleId:role.id,categoryId:cat.id,textId:text.id,voiceId:voice.id};const m=await discordMember(g.discordId);if(m)await m.roles.add(role);return true}catch(e){log("group_error",{groupId:g.id,error:e.message});return false}}
