function safeHttpUrl(value){try{const u=new URL(String(value||""));const h=u.hostname.toLowerCase();if(!["https:","http:"].includes(u.protocol)||!h||h==="localhost"||h.endsWith(".local")||h==="::1"||/^127\./.test(h)||/^10\./.test(h)||/^192\.168\./.test(h)||/^169\.254\./.test(h)||/^172\.(1[6-9]|2\d|3[01])\./.test(h))return "";return u.toString()}catch{return ""}}
