const cinemaPlayers=new Map();
function stopCinemaPlayback(guildId){const old=cinemaPlayers.get(guildId);if(!old)return;try{old.player.stop(true)}catch{}try{old.ffmpeg?.kill("SIGTERM")}catch{}try{old.connection.destroy()}catch{}cinemaPlayers.delete(guildId)}
