app.post("/api/cinema/start",auth,owner,async(q,s)=>{const item=store.settings.cinema.find(x=>x.id===q.body.itemId);if(!item)return s.status(404).json({error:"الفيلم غير موجود في المكتبة"});const voiceChannelId=store.settings.cinemaVoiceChannelId;let voicePlayback=false,playbackMessage="";if(voiceChannelId&&guild&&client.isReady()&&item.mediaType!=="youtube"&&item.mediaType!=="link"){try{if(!ffmpegPath)throw Error("FFmpeg غير متاح في بيئة التشغيل");const channel=guild.channels.cache.get(voiceChannelId);if(!channel||![ChannelType.GuildVoice,ChannelType.GuildStageVoice].includes(channel.type))throw Error("الروم الصوتي المحفوظ غير متاح");const me=await guild.members.fetchMe();if(!me.permissionsIn(channel).has([PermissionFlagsBits.Connect,PermissionFlagsBits.Speak]))throw Error("البوت يحتاج صلاحية Connect وSpeak في الروم");stopCinemaPlayback(guild.id);const connection=joinVoiceChannel({channelId:channel.id,guildId:guild.id,adapterCreator:guild.voiceAdapterCreator,selfDeaf:false});await entersState(connection,VoiceConnectionStatus.Ready,15000);const ffmpeg=spawn(ffmpegPath,["-hide_banner","-loglevel","error","-reconnect","1","-reconnect_streamed","1","-reconnect_delay_max","5","-i",item.url,"-vn","-f","s16le","-ar","48000","-ac","2","pipe:1"],{stdio:["ignore","pipe","ignore"]});const player=createAudioPlayer({behaviors:{noSubscriber:NoSubscriberBehavior.Pause}});const resource=createAudioResource(ffmpeg.stdout,{inputType:StreamType.Raw});const playback={connection,player,ffmpeg,itemId:item.id};cinemaPlayers.set(guild.id,playback);connection.subscribe(player);player.once(AudioPlayerStatus.Idle,()=>{if(cinemaPlayers.get(guild.id)===playback)stopCinemaPlayback(guild.id)});player.on("error",e=>{console.warn("Cinema audio playback failed:",e.message);if(cinemaPlayers.get(guild.id)===playback)stopCinemaPlayback(guild.id)});ffmpeg.once("error",e=>console.warn("Cinema FFmpeg error:",e.message));ffmpeg.once("close",code=>{if(code!==0)console.warn("Cinema FFmpeg exited:",code)});player.play(resource);voicePlayback=true;playbackMessage="البوت متصل بالروم ويشغّل مسار الصوت للمحتوى المباشر."}catch(e){stopCinemaPlayback(guild.id);playbackMessage=e.message;console.warn("Cinema voice playback unavailable:",e.message)}}else if(voiceChannelId)playbackMessage=item.mediaType==="youtube"?"روابط YouTube تُعرض في المتصفح؛ تشغيل صوتها عبر البوت غير مفعّل.": "لم يتوفر تشغيل صوتي مباشر لهذا الرابط.";
const textChannelId=process.env.DISCORD_NOTIFICATION_CHANNEL_ID||guild?.systemChannelId;let notified=false;if(client.isReady()&&textChannelId){try{const channel=await client.channels.fetch(textChannelId);if(channel?.isTextBased()){await channel.send({content:"🎬 بدأت جلسة مشاهدة MLD: **"+item.title+"**\n"+item.url});notified=true}}catch(e){console.warn("Cinema announcement failed:",e.message)}}log("cinema_start",{itemId:item.id,voiceChannelId,voicePlayback});s.json({ok:true,item:publicCinemaItem(item),voiceChannelId,voicePlayback,playbackMessage,notified,mode:"watch-party",note:"الفيديو يُعرض في المتصفح؛ البوت يشغّل الصوت فقط للرابط المباشر المدعوم."})});
app.post("/api/ai/chat",async(q,s)=>{const apiKey=process.env.OPENAI_API_KEY;if(!apiKey)return s.status(503).json({error:"خدمة الذكاء الاصطناعي تحتاج ضبط OPENAI_API_KEY في Railway أولاً."});const messages=Array.isArray(q.body.messages)?q.body.messages.slice(-12):[];const userText=messages.filter(m=>m&&m.role==="user").map(m=>String(m.content||"")).join("\n");if(!userText.trim()||userText.length>12000)return s.status(400).json({error:"اكتب رسالة واضحة لا تتجاوز 12000 حرف."});const safeMessages=messages.filter(m=>m&&["user","assistant"].includes(m.role)&&typeof m.content==="string").map(m=>({role:m.role,content:m.content.slice(0,4000)}));try{const r=await fetch(process.env.OPENAI_BASE_URL||"https://api.openai.com/v1/chat/completions",{method:"POST",headers:{"Authorization":"Bearer "+apiKey,"Content-Type":"application/json"},body:JSON.stringify({model:process.env.OPENAI_MODEL||"gpt-4o-mini",temperature:0.7,max_tokens:900,messages:[{role:"system",content:"أنت مساعد MLD الذكي داخل مجتمع عربي. أجب بالعربية بوضوح، ولا تدّع تنفيذ إجراءات أو الوصول إلى بيانات غير متاحة."},...safeMessages]})});const data=await r.json().catch(()=>({}));if(!r.ok)return s.status(502).json({error:"تعذر إكمال الطلب من مزود الذكاء الاصطناعي. تحقق من المفتاح وحدود الاستخدام."});const answer=data.choices?.[0]?.message?.content;if(!answer)return s.status(502).json({error:"وصل رد غير مكتمل من خدمة الذكاء الاصطناعي."});s.json({answer,model:data.model||process.env.OPENAI_MODEL||"gpt-4o-mini"})}catch(e){console.error("AI request failed:",e.message);s.status(502).json({error:"تعذر الاتصال بخدمة الذكاء الاصطناعي."})}});
function botCryptoKey(){const raw=process.env.BOT_TOKEN_ENCRYPTION_KEY||"";if(/^[0-9a-f]{64}$/i.test(raw))return Buffer.from(raw,"hex");try{const b=Buffer.from(raw,"base64");return b.length===32?b:null}catch{return null}}
function encryptBotToken(token){const key=botCryptoKey();if(!key)throw Error("BOT_TOKEN_ENCRYPTION_KEY غير مضبوط في Railway");const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv("aes-256-gcm",key,iv),data=Buffer.concat([cipher.update(token,"utf8"),cipher.final()]);return {tokenCipher:data.toString("base64"),tokenIv:iv.toString("base64"),tokenTag:cipher.getAuthTag().toString("base64")}}
function decryptBotToken(bot){const key=botCryptoKey();if(!key)throw Error("BOT_TOKEN_ENCRYPTION_KEY غير مضبوط في Railway");const decipher=crypto.createDecipheriv("aes-256-gcm",key,Buffer.from(bot.tokenIv,"base64"));decipher.setAuthTag(Buffer.from(bot.tokenTag,"base64"));return Buffer.concat([decipher.update(Buffer.from(bot.tokenCipher,"base64")),decipher.final()]).toString("utf8")}
const managedBotClients=new Map();
function publicManagedBot(b){return {id:b.id,userId:b.userId,botId:b.botId,botName:b.botName,guildId:b.guildId,status:managedBotClients.get(b.id)?.isReady()?"online":b.status||"offline",createdAt:b.createdAt}}
async function bootManagedBots(){if(!botCryptoKey())return;for(const b of store.bots){try{const c=new Client({intents:[GatewayIntentBits.Guilds]});c.once("ready",()=>{b.status="online";save()});c.on("error",e=>console.error("Managed bot error:",b.id,e.message));await c.login(decryptBotToken(b));managedBotClients.set(b.id,c)}catch(e){b.status="offline";console.warn("Managed bot could not start:",b.id,e.message)}}}
app.get("/api/bots",auth,(q,s)=>s.json(store.bots.filter(b=>b.userId===q.user.id).map(publicManagedBot)));
app.post("/api/bots",auth,async(q,s)=>{const token=String(q.body.token||"").trim(),guildId=String(q.body.guildId||"").trim();if(!token||!guildId)return s.status(400).json({error:"أدخل توكن البوت ومعرّف السيرفر"});if(!botCryptoKey())return s.status(503).json({error:"إعداد تشفير توكنات البوتات مفقود: BOT_TOKEN_ENCRYPTION_KEY"});if(store.bots.some(b=>b.userId===q.user.id&&b.guildId===guildId))return s.status(409).json({error:"لديك بوت مسجل لهذا السيرفر بالفعل"});let test;try{test=new Client({intents:[GatewayIntentBits.Guilds]});await test.login(token);const g=await test.guilds.fetch(guildId).catch(()=>null);if(!g)return s.status(400).json({error:"البوت غير موجود في السيرفر المحدد. أضفه إلى السيرفر أولاً."});const me=await g.members.fetchMe().catch(()=>null);if(!me||!me.permissions.has(PermissionFlagsBits.Administrator))return s.status(403).json({error:"يجب منح البوت صلاحية Administrator في السيرفر"});const sealed=encryptBotToken(token),record={id:id(),userId:q.user.id,botId:test.user.id,botName:test.user.username,guildId,...sealed,status:"online",createdAt:new Date().toISOString()};store.bots.push(record);save();managedBotClients.set(record.id,test);test.once("ready",()=>{record.status="online";save()});test.on("error",e=>console.error("Managed bot error:",record.id,e.message));log("bot_add",{botId:record.botId,guildId});return s.status(201).json(publicManagedBot(record))}catch(e){return s.status(400).json({error:"تعذر توصيل البوت. تحقق من التوكن وأن البوت أُضيف للسيرفر: "+String(e.message||"").slice(0,180)})}finally{if(test&&!store.bots.some(b=>managedBotClients.get(b.id)===test))try{test.destroy()}catch{}}});
app.delete("/api/bots/:id",auth,(q,s)=>{const b=store.bots.find(x=>x.id===q.params.id&&x.userId===q.user.id);if(!b)return s.status(404).json({error:"البوت غير موجود"});managedBotClients.get(b.id)?.destroy();managedBotClients.delete(b.id);store.bots=store.bots.filter(x=>x.id!==b.id);save();log("bot_delete",{id:b.id});s.json({ok:true})});
