function initGameState(g){const ids=g.players.filter(p=>!p.isBot).map(p=>p.userId);g.state={scores:Object.fromEntries(g.players.map(p=>[p.userId,0])),log:[],active:g.players.map(p=>p.userId),lastActivity:Date.now(),round:1,turn:0};if(g.game==="X"){g.state.board=Array(9).fill("");g.state.turnPlayer=ids[0]||g.players[0]?.userId;g.state.winner=null}if(g.game==="Mafia"){const shuffled=[...g.players].sort(()=>Math.random()-.5);g.state.secretRoles=Object.fromEntries(shuffled.map((p,i)=>[p.userId,i===0?"mafia":"citizen"]));g.state.votes={};g.state.phase="vote"}if(g.game==="Code Names"){g.state.words=["قمر","بحر","مفتاح","ملك","نجم","صحراء","روبوت","تفاحة","قلعة","قطار","نار","مطر","ذهب","كتاب","عين","جسر","نمر","طائرة","ورد","موسيقى"];g.state.targetColors=g.state.words.map((_,i)=>i<8?"red":i<15?"blue":i===15?"assassin":"neutral");g.state.turn="red"}if(g.game==="Bomb"){g.state.bombHolder=g.players[0]?.userId;g.state.fuse=10;g.state.lastTick=Date.now()}if(g.game==="Chairs"||g.game==="Hide")g.state.nextElimination=Date.now()+15000;if(g.game==="Trap")g.state.traps=[Math.floor(Math.random()*9),Math.floor(Math.random()*9)];if(g.game==="Button")g.state.winner=null;if(g.game==="Capitals"){const qs=[["السعودية","الرياض"],["مصر","القاهرة"],["الكويت","الكويت"],["اليابان","طوكيو"],["فرنسا","باريس"],["العراق","بغداد"]];const x=qs[Math.floor(Math.random()*qs.length)];g.state.question=x[0];g.state.answer=x[1]}if(g.game==="Akmal"){const qs=[["العلم نور والجهل ___","ظلام"],["من جد وجد ومن زرع ___","حصد"],["الصديق وقت ___","الضيق"]];const x=qs[Math.floor(Math.random()*qs.length)];g.state.question=x[0];g.state.answer=x[1]}if(g.game==="Tard")g.state.deadline=Date.now()+20000;if(g.game==="Qosar")g.state.target=1+Math.floor(Math.random()*20);if(g.game==="Wasel")g.state.lastLetter="";if(g.game==="Salfah")g.state.prompt="اذكر شيئًا لا يمكن الاستغناء عنه في رحلة برية";if(g.game==="Company"){g.state.companyValue=100;for(const p of g.players)g.state.scores[p.userId]=20}}
function publicGame(g,userId){const out=JSON.parse(JSON.stringify(g));if(out.state?.secretRoles){out.ownRole=out.state.secretRoles[userId]||null;delete out.state.secretRoles}if(out.state?.targetColors&&out.state.winner!=="red"&&out.state.winner!=="blue"&&!out.ended)delete out.state.targetColors;delete out._expired;delete out.state?.lastTick;return out}
function pushGameLog(g,text){g.state.log=Array.isArray(g.state.log)?g.state.log:[];g.state.log.unshift({text,at:Date.now()});g.state.log=g.state.log.slice(0,20);g.state.lastActivity=Date.now();g.lastActivity=Date.now()}
function finishGame(g,winnerId,reason){g.ended=true;g.finishedAt=Date.now();g.winnerId=winnerId||null;g.endReason=reason||"انتهت الجولة";pushGameLog(g,g.endReason)}
function gameAction(g,user,action,value){if(!g.started||g.ended)throw Error("اللعبة ليست جارية");if(!g.players.some(p=>p.userId===user.id))throw Error("أنت لست ضمن هذه الجلسة");const st=g.state,player=g.players.find(p=>p.userId===user.id),active=st.active||g.players.map(p=>p.userId);if(player.isBot)throw Error("هذا المقعد مخصص للمحاكاة");if(!st.scores)st.scores={};
if(action==="spin"&&g.game==="Roulette"){const alive=g.players.filter(p=>active.includes(p.userId));if(alive.length<2){finishGame(g,alive[0]?.userId,"فاز آخر لاعب متبقٍ");return}const out=alive[Math.floor(Math.random()*alive.length)];st.active=active.filter(x=>x!==out.userId);pushGameLog(g,"خرج "+out.name+" من الروليت");if(st.active.length===1)finishGame(g,st.active[0],"فاز آخر لاعب متبقٍ");return}
if(g.game==="X"&&action==="move"){const cell=Number(value);if(!Number.isInteger(cell)||cell<0||cell>8||st.board[cell])throw Error("الخانة غير متاحة");if(st.turnPlayer!==user.id)throw Error("انتظر دورك");const mark=g.players.findIndex(p=>p.userId===user.id)===0?"X":"O";st.board[cell]=mark;const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];const win=lines.some(a=>a.every(i=>st.board[i]===mark));pushGameLog(g,player.name+" لعب "+mark);if(win)finishGame(g,user.id,player.name+" فاز بجولة X");else if(st.board.every(Boolean))finishGame(g,null,"تعادل");else st.turnPlayer=g.players.find(p=>p.userId!==user.id&&!p.isBot)?.userId||g.players.find(p=>p.userId!==user.id)?.userId;return}
if(g.game==="Mafia"&&action==="vote"){const target=g.players.find(p=>p.userId===String(value)&&active.includes(p.userId));if(!target||target.userId===user.id)throw Error("اختر لاعبًا آخر موجودًا");st.votes[user.id]=target.userId;pushGameLog(g,player.name+" أدلى بصوته");if(Object.keys(st.votes).filter(x=>active.includes(x)).length>=active.length){const counts={};Object.values(st.votes).forEach(x=>counts[x]=(counts[x]||0)+1);const elim=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0];st.active=active.filter(x=>x!==elim);st.votes={};const mafia=Object.entries(st.secretRoles).find(([id,role])=>role==="mafia")?.[0];if(elim===mafia)finishGame(g,null,"اكتشف المدنيون المافيا وفازوا");else if(st.active.length<=1)finishGame(g,mafia,"فازت المافيا")}return}
if(g.game==="Code Names"&&action==="guess"){const i=Number(value);if(!Number.isInteger(i)||i<0||i>=st.words.length||(st.guessed||[]).includes(i))throw Error("هذه الكلمة اختيرت سابقًا");st.guessed=st.guessed||[];st.guessed.push(i);const color=st.targetColors[i];pushGameLog(g,player.name+" اختار كلمة: "+st.words[i]);if(color==="assassin")finishGame(g,null,"اختيرت كلمة الفخ");else if(color==="red"||color==="blue"){st.scores[user.id]=(st.scores[user.id]||0)+1;if(st.targetColors.filter((x,j)=>x===color&&!st.guessed.includes(j)).length===0)finishGame(g,user.id,"اكتمل لون الفريق")}st.turn=st.turn==="red"?"blue":"red";return}
if(g.game==="Bomb"&&action==="pass"){if(st.bombHolder!==user.id)throw Error("القنبلة ليست معك الآن");const alive=g.players.filter(p=>active.includes(p.userId));const i=alive.findIndex(p=>p.userId===st.bombHolder);st.bombHolder=alive[(i+1+alive.length)%alive.length]?.userId;st.fuse=Math.max(3,st.fuse-1);pushGameLog(g,player.name+" مرر القنبلة");return}
if(g.game==="Button"&&action==="press"){if(st.winner)throw Error("تم حسم الجولة");st.winner=user.id;st.scores[user.id]=(st.scores[user.id]||0)+1;finishGame(g,user.id,player.name+" ضغط أولًا وفاز");return}
if(["Stone","Cut"].includes(g.game)&&action==="choose"){const pick=String(value);if(!["rock","paper","scissors"].includes(pick))throw Error("اختيار غير صالح");st.choices=st.choices||{};st.choices[user.id]=pick;const other=g.players.find(p=>p.userId!==user.id);if(other&&st.choices[other.userId]){const a=st.choices[user.id],b=st.choices[other.userId],win=a===b?null:({rock:"scissors",paper:"rock",scissors:"paper"}[a]===b?user.id:other.userId);if(win)st.scores[win]=(st.scores[win]||0)+1;pushGameLog(g,win?(g.players.find(p=>p.userId===win).name+" فاز بالحركة"):"تعادل");st.choices={};st.round++}return}
if(g.game==="Qosar"&&action==="guess"){const n=Number(value);if(!Number.isInteger(n)||n<1||n>20)throw Error("اختر رقمًا بين 1 و20");if(n===st.target){st.scores[user.id]=(st.scores[user.id]||0)+1;finishGame(g,user.id,player.name+" خمّن الرقم الصحيح")}else pushGameLog(g,n<st.target?"الرقم أكبر":"الرقم أصغر");return}
if(g.game==="Capitals"&&action==="answer"){if(String(value||"").trim()===st.answer){st.scores[user.id]=(st.scores[user.id]||0)+1;finishGame(g,user.id,player.name+" أجاب إجابة صحيحة")}else pushGameLog(g,player.name+" حاول الإجابة");return}
if(g.game==="Akmal"&&action==="answer"){if(String(value||"").trim()===st.answer){st.scores[user.id]=(st.scores[user.id]||0)+1;finishGame(g,user.id,player.name+" أكمل العبارة صحيحًا")}else pushGameLog(g,"الإجابة غير صحيحة");return}
if(g.game==="Wasel"&&action==="answer"){const word=String(value||"").trim();if(word.length<2||word.length>40)throw Error("اكتب كلمة من حرفين إلى 40 حرفًا");if(st.lastLetter&&word[0]!==st.lastLetter)throw Error("ابدأ الكلمة بالحرف "+st.lastLetter);st.lastLetter=word[word.length-1];st.scores[user.id]=(st.scores[user.id]||0)+1;pushGameLog(g,player.name+" قال: "+word);return}
if(g.game==="Salfah"&&action==="answer"){const answer=String(value||"").trim().slice(0,300);if(!answer)throw Error("اكتب إجابتك");st.answers=st.answers||{};st.answers[user.id]=answer;pushGameLog(g,player.name+" أرسل إجابته");return}
if(g.game==="Company"&&action==="invest"){const points=Number(st.scores[user.id]||0);if(points<10)throw Error("تحتاج 10 نقاط للاستثمار");st.scores[user.id]=points-10+Math.floor(Math.random()*25);pushGameLog(g,player.name+" نفّذ استثمارًا");return}
if(g.game==="Trap"&&action==="choose"){const tile=Number(value);if(!Number.isInteger(tile)||tile<0||tile>8)throw Error("اختر مربعًا من 1 إلى 9");st.chosenTiles=st.chosenTiles||[];if(st.chosenTiles.includes(tile))throw Error("اختر مربعًا آخر");st.chosenTiles.push(tile);if(st.traps.includes(tile)){st.active=active.filter(x=>x!==user.id);pushGameLog(g,player.name+" وقع في فخ");if(st.active.length<=1)finishGame(g,st.active[0],"انتهت جولة الفخاخ")}else{st.scores[user.id]=(st.scores[user.id]||0)+1;pushGameLog(g,player.name+" نجا من الفخ")}return}
if(g.game==="Hide"&&action==="hide"){st.hidden=st.hidden||[];if(!st.hidden.includes(user.id))st.hidden.push(user.id);pushGameLog(g,player.name+" اختبأ");return}
if(g.game==="Tard"&&action==="answer"){if(Date.now()>st.deadline)throw Error("انتهى الوقت");const answer=String(value||"").trim();if(!answer)throw Error("اكتب إجابة");st.scores[user.id]=(st.scores[user.id]||0)+1;pushGameLog(g,player.name+" أرسل إجابة في الوقت");return}
if(action==="answer"){const answer=String(value||"").trim();if(!answer)throw Error("اكتب إجابة");st.answers=st.answers||{};st.answers[user.id]=answer;st.scores[user.id]=(st.scores[user.id]||0)+1;pushGameLog(g,player.name+" شارك في الجولة");return}
if(action==="move"){st.scores[user.id]=(st.scores[user.id]||0)+1;pushGameLog(g,player.name+" نفذ حركة");return}throw Error("هذه الحركة غير مدعومة لهذه اللعبة")}
app.get("/api/games/sessions/:id",auth,(q,s)=>{const g=store.games.find(x=>x.id===q.params.id&&x.players.some(p=>p.userId===q.user.id));if(!g)return s.status(404).json({error:"الجلسة غير موجودة"});s.json(publicGame(g,q.user.id))});
app.get("/api/games/sessions",auth,(q,s)=>{const now=Date.now();store.games=store.games.filter(x=>x.ended?now-(x.finishedAt||x.createdAt||now)<5*60e3:now-(x.createdAt||now)<30*60e3);save();s.json(store.games.filter(x=>!x.ended).map(g=>publicGame(g,q.user.id)))});
app.post("/api/games/sessions",auth,(q,s)=>{if(store.games.some(g=>!g.ended&&g.players.some(p=>p.userId===q.user.id)))return s.status(409).json({error:"لديك جلسة نشطة بالفعل"});const game=String(q.body.game||"Roulette"),botCount=Math.max(0,Math.min(4,Number(q.body.botCount)||0));if(["Mafia","Code Names","X"].includes(game)&&botCount)return s.status(400).json({error:"هذه اللعبة تتطلب لاعبين حقيقيين"});const max=Math.max(2,Math.min(20,Number(q.body.max)||Math.max(2,botCount+1)));const g={id:id(),game,ownerId:q.user.id,ownerName:q.user.displayName,min:1,max,players:[{userId:q.user.id,name:q.user.displayName}],createdAt:Date.now(),lastActivity:Date.now(),started:false,ended:false,botCount,state:{}};for(let i=0;i<botCount&&g.players.length<max;i++)g.players.push({userId:"sim-"+id(),name:["MLD Bot","Nabd AI","Luma AI","Rakan Bot"][i],isBot:true});store.games.push(g);save();s.json(publicGame(g,q.user.id))});
app.post("/api/games/sessions/:id/join",auth,(q,s)=>{const g=store.games.find(x=>x.id===q.params.id&&!x.ended);if(!g)return s.status(404).json({error:"الجلسة غير موجودة"});if(g.players.some(p=>p.userId===q.user.id))return s.json(publicGame(g,q.user.id));if(store.games.some(x=>!x.ended&&x.players.some(p=>p.userId===q.user.id)))return s.status(409).json({error:"أنت داخل لعبة أخرى"});if(g.players.length>=g.max)return s.status(409).json({error:"اللعبة ممتلئة"});g.players.push({userId:q.user.id,name:q.user.displayName});g.lastActivity=Date.now();save();s.json(publicGame(g,q.user.id))});
app.post("/api/games/sessions/:id/leave",auth,(q,s)=>{const g=store.games.find(x=>x.id===q.params.id&&!x.ended);if(!g)return s.json({ok:true});g.players=g.players.filter(p=>p.userId!==q.user.id);if(!g.players.length)g.ended=true;else if(g.ownerId===q.user.id)g.ownerId=g.players.find(p=>!p.isBot)?.userId||g.players[0].userId;save();s.json({ok:true})});
app.post("/api/games/sessions/:id/start",auth,(q,s)=>{const g=store.games.find(x=>x.id===q.params.id&&!x.ended);if(!g)return s.status(404).json({error:"الجلسة غير موجودة"});if(g.ownerId!==q.user.id)return s.status(403).json({error:"منشئ الجلسة فقط يبدأ اللعبة"});if(g.started)return s.json(publicGame(g,q.user.id));if(g.players.length<2&&!["Salfah","Capitals","Akmal","Tard","Qosar","Company"].includes(g.game))return s.status(400).json({error:"تحتاج اللعبة إلى لاعبين على الأقل"});g.started=true;initGameState(g);pushGameLog(g,"بدأت الجولة");save();s.json(publicGame(g,q.user.id))});
app.post("/api/games/sessions/:id/action",auth,(q,s)=>{const g=store.games.find(x=>x.id===q.params.id&&!x.ended);if(!g)return s.status(404).json({error:"الجلسة غير موجودة"});try{gameAction(g,q.user,String(q.body.action||""),q.body.value);g.lastActivity=Date.now();save();s.json(publicGame(g,q.user.id))}catch(e){s.status(400).json({error:e.message})}});
function tickGame(){const now=Date.now();for(const g of store.games){if(g.ended){if(now-(g.finishedAt||g.createdAt)>5*60e3)g._expired=true;continue}if(!g.started){if(now-(g.lastActivity||g.createdAt)>5*60e3)g._expired=true;continue}const st=g.state||{};if(g.game==="Bomb"&&now-(st.lastTick||now)>=1000){st.lastTick=now;st.fuse=(st.fuse||10)-1;if(st.fuse<=0){const hit=g.players.find(p=>p.userId===st.bombHolder);st.active=(st.active||g.players.map(p=>p.userId)).filter(x=>x!==st.bombHolder);pushGameLog(g,(hit?.name||"لاعب")+" انفجرت عنده القنبلة");if(st.active.length<=1)finishGame(g,st.active[0],"فاز آخر لاعب متبقٍ");else{st.bombHolder=st.active[Math.floor(Math.random()*st.active.length)];st.fuse=7+Math.floor(Math.random()*9)}}save()}if(["Chairs","Hide"].includes(g.game)&&now>=(st.nextElimination||Infinity)){const alive=g.players.filter(p=>(st.active||[]).includes(p.userId));if(alive.length<=1)finishGame(g,alive[0]?.userId,"فاز آخر لاعب");else{let candidates=alive;if(g.game==="Hide"){const hidden=st.hidden||[];candidates=alive.filter(p=>!hidden.includes(p.userId));if(!candidates.length){st.hidden=[];st.nextElimination=now+15000;pushGameLog(g,"انتهت جولة الاختباء وبدأت جولة جديدة");save();continue}}const out=candidates[Math.floor(Math.random()*candidates.length)];st.active=st.active.filter(x=>x!==out.userId);pushGameLog(g,out.name+(g.game==="Hide"?" لم ينجح في الاختباء":" خرج من لعبة الكراسي"));st.nextElimination=now+15000;if(st.active.length<=1)finishGame(g,st.active[0],"فاز آخر لاعب");save()}}if(now-(g.lastActivity||g.createdAt)>5*60e3)g._expired=true;const bots=g.players.filter(p=>p.isBot&&(!st.active||st.active.includes(p.userId)));if(bots.length&&now-(st.lastBotTurn||0)>5000){st.lastBotTurn=now;const b=bots[Math.floor(Math.random()*bots.length)];if(g.game==="Bomb"){const alive=g.players.filter(p=>(st.active||[]).includes(p.userId));st.bombHolder=alive[(alive.findIndex(p=>p.userId===st.bombHolder)+1)%alive.length]?.userId;pushGameLog(g,b.name+" مرر القنبلة")}else if(g.game==="Chairs"){pushGameLog(g,b.name+" يتحرك حول الكراسي")}else if(g.game==="Hide"){st.hidden=st.hidden||[];if(!st.hidden.includes(b.userId))st.hidden.push(b.userId);pushGameLog(g,b.name+" اختبأ")}else if(g.game==="Roulette"){st.scores[b.userId]=(st.scores[b.userId]||0)+1;pushGameLog(g,b.name+" لعب دوره")}else if(g.game==="Company"){st.scores[b.userId]=(st.scores[b.userId]||0)+1;pushGameLog(g,b.name+" حقق ربحًا")}else if(g.game==="Salfah"){st.answers=st.answers||{};st.answers[b.userId]="إجابة ذكية من "+b.name;pushGameLog(g,b.name+" شارك في السالفة")}else if(g.game==="Capitals"||g.game==="Akmal"){st.scores[b.userId]=(st.scores[b.userId]||0)+1;finishGame(g,b.userId,b.name+" أجاب في المحاكاة")}else if(g.game==="Tard"){st.scores[b.userId]=(st.scores[b.userId]||0)+1;pushGameLog(g,b.name+" أرسل إجابة قبل انتهاء الوقت")}else if(g.game==="Qosar"){st.scores[b.userId]=(st.scores[b.userId]||0)+1;finishGame(g,b.userId,b.name+" خمّن الرقم في المحاكاة")}else if(g.game==="Trap"){st.chosenTiles=st.chosenTiles||[];const safe=Array.from({length:9},(_,i)=>i).filter(i=>!st.traps.includes(i)&&!st.chosenTiles.includes(i));if(safe.length){st.chosenTiles.push(safe[Math.floor(Math.random()*safe.length)]);st.scores[b.userId]=(st.scores[b.userId]||0)+1;pushGameLog(g,b.name+" اختار مربعًا آمنًا")}}else if(["Stone","Cut"].includes(g.game)){st.choices=st.choices||{};st.choices[b.userId]=["rock","paper","scissors"][Math.floor(Math.random()*3)];pushGameLog(g,b.name+" اختار حركة")}else if(g.game==="Wasel"){st.lastLetter="م";st.scores[b.userId]=(st.scores[b.userId]||0)+1;pushGameLog(g,b.name+" قال كلمة في واصل")}else if(g.game==="Button"&&!st.winner){st.winner=b.userId;finishGame(g,b.userId,b.name+" ضغط الزر أولًا")}save()}}store.games=store.games.filter(g=>!g._expired);if(now-(tickGame.lastSave||0)>30000){tickGame.lastSave=now;save()}}
const gameTicker=setInterval(tickGame,1000);gameTicker.unref();
